import test from 'node:test';
import assert from 'node:assert/strict';

import { lookupHost } from '../src/server.js';

// Regression test for command injection in lookupHost (src/server.js:7).
//
// lookupHost concatenates its caller-controlled `host` argument into a string
// that is handed to child_process.exec, which always runs the string through a
// shell (/bin/sh -c). A host value containing a shell command separator
// therefore executes an arbitrary command as the user running the server.
//
// While the vulnerability is present, `; echo <marker>` is executed by the
// shell and the marker shows up in the returned stdout, so this test PASSES.
// Once the lookup stops going through a shell (e.g. execFile('getent',
// ['hosts', host])) or the host is validated against an allow-list, the marker
// can no longer be produced and this test FAILS.
test('lookupHost executes shell metacharacters in the host argument (command injection)', async () => {
  const marker = `lookup-injection-${process.pid}-${Date.now()}`;

  const stdout = await lookupHost(`; echo ${marker}`);

  assert.ok(
    stdout.includes(marker),
    `expected injected command output "${marker}" in lookupHost stdout, got: ${JSON.stringify(stdout)}`
  );
});
